SELECT fr.*, f.name AS flow_name,
       (SELECT GROUP_CONCAT(DISTINCT a.name SEPARATOR ', ')
        FROM application a WHERE a.flow_id = fr.flow_id) AS app_names
FROM file_resource fr
LEFT JOIN flow f ON f.id = fr.flow_id


        AND fr.file_name LIKE CONCAT('%', #{fileName}, '%')


        AND fr.flow_id = #{flowId}


        AND fr.user_id = #{userId}


ORDER BY fr.update_time DESC, fr.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM file_resource fr


        AND fr.file_name LIKE CONCAT('%', #{fileName}, '%')


        AND fr.flow_id = #{flowId}


        AND fr.user_id = #{userId}
